CREATE TEMPORARY VIEW before_data_${grass_region_without_quote} AS
select
     vitem_id
    ,order_cnt_nd
from srdi_mart.dws_sr_data_warehouse_vsku_vitem_nd
WHERE grass_region IN (${grass_region}) AND local_date = date_add(${local_date}, -1)
;
--sql_divide_splitter--
-- it will be used for current day logic judge，so use the fastest source，not use our dwd source
CREATE TEMPORARY VIEW today_order_${grass_region_without_quote} AS
SELECT
    spu_vsku_item_id as vitem_id
   ,sum(order_fraction) as order_cnt
FROM mp_order.dwd_spu_vsku_order_item_df__reg_live
where grass_region in (${grass_region})  and grass_date = ${local_date}
group by
    spu_vsku_item_id
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW today_imp_${grass_region_without_quote} AS
select
     item_id as vitem_id
    ,sum(if(operation = 'impression',operation_cnt,0))  AS imp_cnt
    ,sum(if(operation = 'click' ,operation_cnt,0)) AS click_cnt
from srdi_mart.dwd_sr_data_warehouse_platform a
inner join (
    SELECT
         vitem_id
    FROM srdi_mart.dim_sr_data_warehouse_vsku_vitem
    where grass_region in (${grass_region})  and local_date = ${local_date}
) b on a.item_id=b.vitem_id
WHERE grass_region IN (${grass_region}) AND local_date = ${local_date} and operation in ('impression','click')
group by
    item_id
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW today_data_${grass_region_without_quote} AS
SELECT
    vitem_id
   ,sum(imp_cnt)   as imp_cnt
   ,sum(click_cnt) as click_cnt
   ,sum(order_cnt) as order_cnt
from (
    SELECT
          vitem_id
         ,0 as imp_cnt
         ,0 as click_cnt
         ,order_cnt
    FROM today_order_${grass_region_without_quote}
    union all
    SELECT
          vitem_id
         ,imp_cnt
         ,click_cnt
         ,0 as order_cnt
    FROM today_imp_${grass_region_without_quote}
) a
group by
    vitem_id
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_vsku_vitem_nd partition(grass_region = ${grass_region}, local_date = ${local_date})
select
     if(a.vitem_id is not null ,a.vitem_id,b.vitem_id) as vitem_id
    ,imp_cnt as imp_cnt_1d
    ,click_cnt as click_cnt_1d
    ,order_cnt as order_cnt_1d
    ,(coalesce(a.order_cnt_nd,0)+coalesce(b.order_cnt,0)) as order_cnt_nd
from before_data_${grass_region_without_quote} a
full outer join today_data_${grass_region_without_quote} b on a.vitem_id=b.vitem_id
;
